@* Vertical sidebar navigation for settings sections *@

<nav class="nav flex-column nav-pills settings-sidebar">
    @foreach (var section in Sections)
    {
        <button class="nav-link text-start @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
            <span class="me-2">@GetIcon(section)</span>@section
        </button>
    }
</nav>

@code {
    [Parameter, EditorRequired] public string ActiveSection { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@using sv_22286447cf18487b8842526d4b3a3d1a.Models

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Profile Settings</h4>

        <div class="row mb-4">
            <div class="col-md-3 text-center">
                <img src="@AvatarUrl" alt="Avatar" class="rounded-circle mb-2" width="120" height="120"
                     style="object-fit: cover; border: 3px solid var(--bs-border-color);" />
                <div class="text-muted small text-break mt-1">@AvatarUrl</div>
            </div>
            <div class="col-md-9">
                <div class="mb-3">
                    <label class="form-label fw-semibold">Display Name</label>
                    <input type="text" class="form-control" @bind="DisplayName" />
                </div>
