                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">
                            <strong>Compact Mode</strong>
                            <div class="text-muted small">Reduce spacing and padding throughout the UI</div>
                        </label>
                    </div>
                </div>
            </div>

            <div class="col-md-6">
                <label class="form-label fw-semibold">Live Preview</label>
                <div class="border rounded @PreviewBgClass" style="@PreviewStyle">
                    <div class="@PreviewPadding">
                        <div class="d-flex align-items-center mb-2 @PreviewPadding">
                            <div class="rounded-circle me-2" style="width:32px;height:32px;background:@PreviewAccent;"></div>
                            <div>
                                <strong style="@PreviewFontStyle">Jane Doe</strong>
                                <div class="@PreviewMutedClass" style="@PreviewSmallFont">jane.doe&#64;example.com</div>
                            </div>
                        </div>
                        <hr class="@PreviewBorderClass" />
                        <p class="mb-2" style="@PreviewFontStyle">
                            This is a preview of how your content will look with the selected appearance settings.
