                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save
        </button>

        @if (_showSuccess)
        {
            <div class="alert alert-success mt-3 mb-0">
                ✅ Appearance settings saved!
            </div>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Settings { get; set; } = null!;
    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _saving;
    private bool _showSuccess;

    protected override void OnParametersSet()
    {
        if (!_saving)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    // Preview computed properties
    private string PreviewBgClass => _theme == "Dark" ? "bg-dark text-white" : "bg-white text-dark";
    private string PreviewAccent => _theme == "Dark" ? "#6ea8fe" : "#0d6efd";
    private string PreviewBtnClass => _theme == "Dark" ? "btn-light" : "btn-primary";
    private string PreviewMutedClass => _theme == "Dark" ? "text-light opacity-75" : "text-muted";
    private string PreviewBorderClass => _theme == "Dark" ? "border-secondary" : "";
    private string PreviewPadding => _compactMode ? "p-2" : "p-3";

    private string PreviewStyle => $"min-height: 180px; font-size: {FontSizePx}; transition: all 0.2s ease;";
    private string PreviewFontStyle => $"font-size: {FontSizePx};";
    private string PreviewSmallFont => $"font-size: {SmallFontSizePx};";

    private string FontSizePx => _fontSize switch
    {
        "Small" => "13px",
        "Large" => "18px",
        _ => "15px"
    };

    private string SmallFontSizePx => _fontSize switch
    {
        "Small" => "11px",
        "Large" => "15px",
        _ => "13px"
    };

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

