{"file_text": "@using sv_22286447cf18487b8842526d4b3a3d1a.Models

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Appearance Settings</h4>

        <div class="row">
            <div class="col-md-6">
                <div class="mb-4">
                    <label class="form-label fw-semibold">Theme</label>
                    <div>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")" value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="mb-4">
                    <label class="form-label fw-semibold">Font Size</label>
                    <div>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")" value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="mb-4">
                    <label class="form-label fw-semibold" for="language">Language</label>
                    <select class="form-select" id="language" @bind="_language">
                        <option value="English">English</option>
                        <option value="Spanish">Spanish</option>
                        <option value="French">French</option>
                        <option value="German">German</option>
                        <option value="Japanese">Japanese</option>
                        <option value="Chinese">Chinese</option>
                    </select>
                </div>

                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">
                            <strong>Compact Mode</strong>
                            <div class="text-muted small">Reduce spacing and padding throughout the UI</div>
                        </label>
                    </div>
                </div>
            </div>

            <div class="col-md-6">
                <label class="form-label fw-semibold">Live Preview</label>
                <div class="border rounded @PreviewBgClass" style="@PreviewStyle">
                    <div class="@PreviewPadding">
                        <div class="d-flex align-items-center mb-2 @PreviewPadding">
                            <div class="rounded-circle me-2" style="width:32px;height:32px;background:@PreviewAccent;"></div>
                            <div>
                                <strong style="@PreviewFontStyle">Jane Doe</strong>
                                <div class="@PreviewMutedClass" style="@PreviewSmallFont">jane.doe&#64;example.com</div>
                            </div>
                        </div>
                        <hr class="@PreviewBorderClass" />
                        <p class="mb-2" style="@PreviewFontStyle">
                            This is a preview of how your content will look with the selected appearance settings.
                        </p>
                        <button class="btn btn-sm @PreviewBtnClass">Sample Button</button>
                    </div>
                </div>
            </div>
        </div>

        <hr />

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @if (_saving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save
        </button>

        @if (_showSuccess)
        {
            <div class="alert alert-success mt-3 mb-0">
                ✅ Appearance settings saved!
            </div>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Settings { get; set; } = null!;
    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _saving;
    private bool _showSuccess;

    protected override void OnParametersSet()
    {
        if (!_saving)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    // Preview computed properties
    private string PreviewBgClass => _theme == "Dark" ? "bg-dark text-white" : "bg-white text-dark";
    private string PreviewAccent => _theme == "Dark" ? "#6ea8fe" : "#0d6efd";
    private string PreviewBtnClass => _theme == "Dark" ? "btn-light" : "btn-primary";
    private string PreviewMutedClass => _theme == "Dark" ? "text-light opacity-75" : "text-muted";
    private string PreviewBorderClass => _theme == "Dark" ? "border-secondary" : "";
    private string PreviewPadding => _compactMode ? "p-2" : "p-3";

    private string PreviewStyle => $"min-height: 180px; font-size: {FontSizePx}; transition: all 0.2s ease;";
    private string PreviewFontStyle => $"font-size: {FontSizePx};";
    private string PreviewSmallFont => $"font-size: {SmallFontSizePx};";

    private string FontSizePx => _fontSize switch
    {
        "Small" => "13px",
        "Large" => "18px",
        _ => "15px"
    };

    private string SmallFontSizePx => _fontSize switch
    {
        "Small" => "11px",
        "Large" => "15px",
        _ => "13px"
    };

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
