<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Profile Settings</h4>

        <div class="row mb-4">
            <div class="col-md-3 text-center">
                <img src="@AvatarUrl" alt="Avatar" class="rounded-circle mb-2" width="120" height="120"
                     style="object-fit: cover; border: 3px solid var(--bs-border-color);" />
                <div class="text-muted small text-break mt-1">@AvatarUrl</div>
            </div>
            <div class="col-md-9">
                <div class="mb-3">
                    <label class="form-label fw-semibold">Display Name</label>
                    <input type="text" class="form-control" @bind="DisplayName" />
                </div>
                <div class="mb-3">
                    <label class="form-label fw-semibold">Email</label>
                    <input type="email" class="form-control" @bind="Email" />
                </div>
                <div class="mb-3">
                    <label class="form-label fw-semibold">Avatar URL</label>
                    <input type="url" class="form-control" @bind="AvatarUrl" />
                </div>
                <div class="mb-3">
                    <label class="form-label fw-semibold">Bio</label>
                    <textarea class="form-control" rows="3" @bind="Bio"></textarea>
                </div>
            </div>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @if (_saving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
        </div>

        @if (_showSuccess)
        {
            <div class="alert alert-success mt-3 mb-0 d-flex align-items-center" role="alert">
                <span class="me-2">✅</span> Profile saved successfully!
            </div>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = null!;
    [Parameter, EditorRequired] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName = "";
    private string Email = "";
    private string AvatarUrl = "";
    private string Bio = "";
    private bool _saving;
    private bool _showSuccess;

    protected override void OnParametersSet()
    {
        if (!_saving)
        {
            LoadFromProfile();
        }
    }

    private void LoadFromProfile()
    {
        DisplayName = Profile.DisplayName;
        Email = Profile.Email;
        AvatarUrl = Profile.AvatarUrl;
        Bio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        LoadFromProfile();
        _showSuccess = false;
    }
}

